from qiskit import QuantumCircuit
import math
from qiskit.circuit.library import MCRYGate

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    N = 1 << n
    if L >= N:
        for i in range(n):
            qc.h(i)
        return qc

    def recurse(pref, bit_idx):
        if bit_idx < 0:
            return
        total = 1 << (bit_idx + 1)
        low = pref
        high = low + total
        cnt = min(L, high) - low
        if cnt <= 0:
            return
        left_high = low + (1 << bit_idx)
        c0 = min(L, left_high) - low
        if c0 < 0:
            c0 = 0
        c1 = cnt - c0

        if c0 == 0:
            theta = math.pi
        elif c1 == 0:
            theta = 0.0
        else:
            p0 = c0 / cnt
            p0 = max(0.0, min(1.0, p0))
            theta = 2.0 * math.acos(math.sqrt(p0))

        controls = list(range(bit_idx + 1, n))
        for j in controls:
            if ((pref >> j) & 1) == 0:
                qc.x(j)

        if controls:
            gate = MCRYGate(theta, len(controls))
            qc.append(gate, controls + [bit_idx])
        else:
            qc.ry(theta, bit_idx)

        for j in controls:
            if ((pref >> j) & 1) == 0:
                qc.x(j)

        # left child  bit = 0
        recurse(pref, bit_idx - 1)
        # right child bit = 1
        pref_right = pref | (1 << bit_idx)
        recurse(pref_right, bit_idx - 1)

    recurse(0, n - 1)
    return qc

from qiskit import QuantumCircuit
from qiskit.circuit.library import MCPhaseGate
import math

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    for i in range(n):
        qc.h(i)

    N = 1 << n
    M = L
    if M >= N:
        return qc
    if M / N > 0.5:
        return qc

    theta = math.asin(math.sqrt(M / N))
    k = 0
    # smallest k with sin^2((2k+1)theta) > 0.5
    while True:
        prob = math.sin((2 * k + 1) * theta) ** 2
        if prob > 0.5:
            break
        k += 1
        if k > 500:          # safety
            break

    # multi-controlled Z = MCPhase(pi, n-1)
    if n == 1:
        phase = None
    else:
        phase = MCPhaseGate(math.pi, n - 1)

    def apply_phase():
        if n == 1:
            qc.z(0)
        else:
            qc.append(phase, range(n))

    for _ in range(k):
        # oracle : mark |i> , i < L
        for i in range(M):
            for j in range(n):
                if ((i >> j) & 1) == 0:
                    qc.x(j)
            apply_phase()
            for j in range(n):
                if ((i >> j) & 1) == 0:
                    qc.x(j)

        # diffusion
        for i in range(n):
            qc.h(i)
        for i in range(n):
            qc.x(i)
        apply_phase()
        for i in range(n):
            qc.x(i)
        for i in range(n):
            qc.h(i)

    return qc
